#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# NUC wizard, part 1: from a fresh Ubuntu Server install to a secured base
# system with Docker, Tailscale and the backup disk. Spec: #64, #72. Guide:
# docs/deployment/1-install-the-nuc.md.
#
# Runs on the NUC itself: sudo bash setup-nuc.sh
# Every stage first checks the machine and skips what is already in place, so
# a second run changes nothing.

ENV_FILE=/etc/chargeonsolar/setup-nuc.env
USER_NAME="${SUDO_USER:-}"
USER_HOME=""

SSH_DROPIN=/etc/ssh/sshd_config.d/10-chargeonsolar.conf
DOCKER_SOURCES=/etc/apt/sources.list.d/docker.sources
DOCKER_DAEMON=/etc/docker/daemon.json
UPGRADES_CONF=/etc/apt/apt.conf.d/52chargeonsolar-unattended-upgrades
TAILSCALE_LIST=/etc/apt/sources.list.d/tailscale.list
FORWARDING_CONF=/etc/sysctl.d/99-tailscale.conf
BACKUP_MOUNT=/backup
SRV_DIRS=(/srv/proxy /srv/chargeonsolar)
PORTS=(22 80 443)
TAILSCALE_CGNAT=100.64.0.0/10 # the addresses Tailscale gives its devices

DONE=()
ALREADY=()
NEXT=()

already_done() {
  ALREADY+=("$1")
  printf '  %s✓ already done:%s nothing to change.\n' "$GREEN" "$RESET"
}
did() {
  DONE+=("$1")
  printf '  %s✓ done%s\n' "$GREEN" "$RESET"
}
# skip_stage "why": the stage gives up; the summary lists it as still to do.
skip_stage() {
  SKIPPED+=("$1")
  warn "skipped: $1"
  pause
}

pkg_installed() { [[ "$(dpkg-query -W -f='${Status}' "$1" 2>/dev/null)" == "install ok installed" ]]; }
apt_install() { DEBIAN_FRONTEND=noninteractive apt-get install -y -q "$@"; }
apt_update() { apt-get update -q; }
ubuntu_codename() {
  # shellcheck source=/dev/null
  (. /etc/os-release && printf '%s' "${UBUNTU_CODENAME:-$VERSION_CODENAME}")
}

# file_is PATH CONTENT: PATH exists and holds exactly CONTENT.
file_is() { [[ -f "$1" && "$(cat "$1")" == "$2" ]]; }

# write_file PATH MODE CONTENT
write_file() {
  install -d -m 0755 "$(dirname "$1")"
  printf '%s\n' "$3" > "$1"
  chmod "$2" "$1"
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$1"
}

ip_to_int() {
  local IFS=. a b c d
  read -r a b c d <<<"$1"
  printf '%s' $(( (a << 24) + (b << 16) + (c << 8) + d ))
}

# ip_in_cidr 192.168.1.20 192.168.1.0/24: IPv4 only.
ip_in_cidr() {
  local ip="$1" net="${2%/*}" bits="${2#*/}" mask
  [[ "$ip" =~ ^[0-9]+(\.[0-9]+){3}$ ]] || return 1
  mask=$(( bits == 0 ? 0 : (0xFFFFFFFF << (32 - bits)) & 0xFFFFFFFF ))
  (( ($(ip_to_int "$ip") & mask) == ($(ip_to_int "$net") & mask) ))
}

valid_cidr() { [[ "$1" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}/([0-9]|[12][0-9]|3[0-2])$ ]]; }

# field_after WORD: the word after WORD in an `ip route` line on stdin.
field_after() { awk -v word="$1" '{ for (i = 1; i < NF; i++) if ($i == word) { print $(i + 1); exit } }'; }

# detected_lan: the subnet of the network card that holds the default route.
detected_lan() {
  local dev
  dev=$(ip -4 route show default | field_after dev)
  [[ -n "$dev" ]] || return 1
  ip -4 route show dev "$dev" proto kernel scope link | awk 'NR == 1 { print $1 }'
}

# The LAN subnet, as confirmed on an earlier run, else as detected. Checks use
# this without asking; choose_lan asks before anything is changed.
LAN_SUBNET=""
LAN_CONFIRMED=0
choose_lan() {
  (( LAN_CONFIRMED )) && return 0
  say "Your home network (the LAN subnet) looks like: ${BOLD}$LAN_SUBNET${RESET}"
  note "It is the range of addresses your router hands out, e.g. 192.168.1.0/24."
  if [[ -z "$LAN_SUBNET" ]] || ! confirm "Is $LAN_SUBNET your home network?"; then
    while :; do
      ask LAN_SUBNET "LAN subnet (like 192.168.1.0/24):" || exit 1
      valid_cidr "$LAN_SUBNET" && break
      warn "That isn't a subnet like 192.168.1.0/24."
    done
  fi
  write_env LAN_SUBNET "$LAN_SUBNET"
  LAN_CONFIRMED=1
}

# ── Stage 1: SSH ──────────────────────────────────────────────────────────

SSH_SETTINGS='# Written by setup-nuc.sh (ChargeOnSolar, #72): SSH logins by key only.
# Sorts before 50-cloud-init.conf, and sshd keeps the first value it reads.
PasswordAuthentication no
KbdInteractiveAuthentication no
PermitRootLogin no
PubkeyAuthentication yes'

# ssh_hardened: sshd's effective settings (sshd -T, lowercase) are SSH_SETTINGS.
ssh_hardened() {
  local config setting
  install -d -m 0755 /run/sshd # sshd -T needs it; with socket activation it may not exist yet
  config=$(sshd -T 2>/dev/null) || return 1
  while read -r setting; do
    grep -qxi "$setting" <<<"$config" || return 1
  done < <(grep -v '^#' <<<"$SSH_SETTINGS")
}

user_key_count() {
  ssh-keygen -l -f "$USER_HOME/.ssh/authorized_keys" 2>/dev/null | wc -l | tr -d ' '
}

# key_login_seen: an SSH login with a key since the NUC booted.
key_login_seen() {
  journalctl -b -q --no-pager -o cat 2>/dev/null | grep -q "^Accepted publickey for $USER_NAME from "
}

nuc_address() {
  local ip
  ip=$(ip -4 route get 1.1.1.1 2>/dev/null | field_after src)
  printf '%s' "${ip:-<the NUC address>}"
}

harden_ssh() {
  if ssh_hardened; then already_done "SSH: key login only"; return; fi

  say "SSH still accepts passwords. After this stage it accepts only SSH keys,"
  say "and never a login as root. First a check that your key works, so you"
  say "can't lock yourself out."
  printf '\n'
  local keys
  while :; do
    keys=$(user_key_count)
    if (( keys > 0 )) && key_login_seen; then
      printf '  %s✓%s %s key(s) may log in as %s, and a key login worked since boot.\n' \
        "$GREEN" "$RESET" "$keys" "$USER_NAME"
      break
    fi
    if (( keys == 0 )); then
      warn "No SSH key may log in as $USER_NAME yet ($USER_HOME/.ssh/authorized_keys)."
      step "On your Mac, run: ssh-copy-id $USER_NAME@$(nuc_address)"
      note "  It asks for your NUC password once and copies your Mac's key."
    else
      warn "$keys key(s) are listed, but no SSH login with a key since the NUC booted."
    fi
    step "In a NEW terminal on your Mac, log in with the key only:"
    say "    ssh -o PasswordAuthentication=no $USER_NAME@$(nuc_address)"
    note "  It must log you in without asking for the NUC password."
    note "  (Your Mac may ask for the passphrase of its own key; that is fine.)"
    if ! confirm "Done that? Check again?"; then
      skip_stage "SSH hardening: no working key login yet. Re-run this wizard once it works."
      return
    fi
  done

  write_file "$SSH_DROPIN" 0644 "$SSH_SETTINGS"
  if ! sshd -t; then
    rm -f "$SSH_DROPIN"
    skip_stage "SSH hardening: sshd rejected the settings (see above); nothing was changed."
    return
  fi
  systemctl try-reload-or-restart ssh.service
  if ! ssh_hardened; then
    skip_stage "SSH hardening: another file in /etc/ssh overrides $SSH_DROPIN (check: sudo sshd -T)"
    return
  fi
  did "SSH: key login only, no passwords, no root"
  warn "Keep this window open. In a NEW Mac terminal, check you can still log in:"
  say "    ssh $USER_NAME@$(nuc_address)"
  NEXT+=("Before closing this window, check a new SSH login from the Mac works.")
  pause
}

# ── Stage 2: Docker ───────────────────────────────────────────────────────

DOCKER_PACKAGES=(docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin)
# Packages that clash with Docker's own, from Docker's install guide.
DOCKER_CLASHES=(docker.io docker-doc docker-compose docker-compose-v2 podman-docker containerd runc)

docker_sources() {
  printf '%s\n' \
    'Types: deb' \
    'URIs: https://download.docker.com/linux/ubuntu' \
    "Suites: $(ubuntu_codename)" \
    'Components: stable' \
    'Signed-By: /etc/apt/keyrings/docker.asc'
}

# Rotated container logs can't fill the SSD.
DOCKER_LOGGING='{"log-driver": "json-file", "log-opts": {"max-size": "10m", "max-file": "3"}}'

docker_logs_rotated() {
  [[ -f "$DOCKER_DAEMON" ]] &&
    jq -e --argjson want "$DOCKER_LOGGING" 'contains($want)' "$DOCKER_DAEMON" >/dev/null 2>&1
}

docker_snap_installed() { command -v snap >/dev/null 2>&1 && snap list docker >/dev/null 2>&1; }

docker_ready() {
  local pkg
  for pkg in "${DOCKER_PACKAGES[@]}"; do pkg_installed "$pkg" || return 1; done
  [[ -f "$DOCKER_SOURCES" ]] && docker_logs_rotated && ! docker_snap_installed
}

install_docker() {
  if docker_ready; then already_done "Docker Engine and Compose"; return; fi

  say "Installing Docker Engine and the Compose plugin from Docker's own apt"
  say "repository (not the snap, not Ubuntu's docker.io), with log rotation."
  printf '\n'
  if docker_snap_installed; then
    warn "The Docker snap is installed. It breaks folders shared with containers."
    if ! confirm "Remove the Docker snap (and its containers and images)?"; then
      skip_stage "Docker: remove the Docker snap first (sudo snap remove --purge docker)"
      return
    fi
    snap remove --purge docker
  fi

  local pkg clashes=()
  for pkg in "${DOCKER_CLASHES[@]}"; do pkg_installed "$pkg" && clashes+=("$pkg"); done
  if (( ${#clashes[@]} )); then
    say "Removing packages that clash with Docker's: ${clashes[*]}"
    DEBIAN_FRONTEND=noninteractive apt-get remove -y -q "${clashes[@]}"
  fi

  install -m 0755 -d /etc/apt/keyrings
  if ! curl -fsSL https://download.docker.com/linux/ubuntu/gpg -o /etc/apt/keyrings/docker.asc; then
    skip_stage "Docker: couldn't download Docker's signing key. Check the internet connection and re-run."
    return
  fi
  chmod a+r /etc/apt/keyrings/docker.asc
  write_file "$DOCKER_SOURCES" 0644 "$(docker_sources)"
  if ! apt_update || ! apt_install "${DOCKER_PACKAGES[@]}"; then
    skip_stage "Docker: apt couldn't install it (see above). Does Docker support Ubuntu $(ubuntu_codename) yet?"
    return
  fi

  if ! docker_logs_rotated; then
    local current='{}'
    [[ -s "$DOCKER_DAEMON" ]] && current=$(cat "$DOCKER_DAEMON")
    write_file "$DOCKER_DAEMON" 0644 "$(jq --argjson want "$DOCKER_LOGGING" '. + $want' <<<"$current")"
    systemctl restart docker
  fi
  systemctl enable --now docker.service containerd.service >/dev/null 2>&1
  docker compose version
  did "Docker Engine and Compose, with log rotation"
  pause
}

# ── Stage 3: docker group ─────────────────────────────────────────────────

add_docker_group() {
  if id -nG "$USER_NAME" | tr ' ' '\n' | grep -qx docker; then
    already_done "$USER_NAME in the docker group"
    return
  fi
  if ! getent group docker >/dev/null; then
    skip_stage "docker group: install Docker first, then re-run"
    return
  fi
  say "Adding $USER_NAME to the docker group, so you can run docker without sudo."
  usermod -aG docker "$USER_NAME"
  did "$USER_NAME in the docker group"
  NEXT+=("Log out and back in, so docker works without sudo.")
  pause
}

# ── Stage 4: security updates ─────────────────────────────────────────────

# ${distro_id} and ${distro_codename} are for apt to fill in, not bash.
# shellcheck disable=SC2016
UPGRADES_SETTINGS='// Written by setup-nuc.sh (ChargeOnSolar, #72).
// Install security updates daily, and nothing else. Reboot at 04:00, and only
// when an update needs it (/var/run/reboot-required), even if someone is
// logged in.
APT::Periodic::Update-Package-Lists "1";
APT::Periodic::Unattended-Upgrade "1";
#clear Unattended-Upgrade::Allowed-Origins;
#clear Unattended-Upgrade::Origins-Pattern;
Unattended-Upgrade::Allowed-Origins {
	"${distro_id}:${distro_codename}-security";
	"${distro_id}ESMApps:${distro_codename}-apps-security";
	"${distro_id}ESM:${distro_codename}-infra-security";
};
Unattended-Upgrade::Automatic-Reboot "true";
Unattended-Upgrade::Automatic-Reboot-WithUsers "true";
Unattended-Upgrade::Automatic-Reboot-Time "04:00";'

# Another file in /etc/apt/apt.conf.d may still add non-security origins after ours.
only_security_origins() {
  ! apt-config dump | grep -E '^Unattended-Upgrade::(Allowed-Origins|Origins-Pattern)' |
    grep -qE -- '-(updates|proposed|backports)'
}

upgrades_ready() {
  pkg_installed unattended-upgrades && file_is "$UPGRADES_CONF" "$UPGRADES_SETTINGS" &&
    systemctl is-enabled --quiet apt-daily.timer apt-daily-upgrade.timer && only_security_origins
}

setup_upgrades() {
  if upgrades_ready; then already_done "Automatic security updates"; return; fi

  say "Turning on automatic security updates. When one needs a reboot (a new"
  say "kernel, say), the NUC restarts at 04:00 that night; otherwise it doesn't."
  printf '\n'
  pkg_installed unattended-upgrades || apt_install unattended-upgrades
  write_file "$UPGRADES_CONF" 0644 "$UPGRADES_SETTINGS"
  systemctl enable --now apt-daily.timer apt-daily-upgrade.timer >/dev/null 2>&1
  if ! only_security_origins; then
    skip_stage "Security updates: other files in /etc/apt/apt.conf.d add non-security updates"
    return
  fi
  did "Automatic security updates, reboot at 04:00 when needed"
  pause
}

# ── Stage 5: firewall ─────────────────────────────────────────────────────

ufw_wanted_rules() {
  local port
  for port in "${PORTS[@]}"; do
    printf 'ufw allow from %s to any port %s proto tcp\n' "$LAN_SUBNET" "$port"
    printf 'ufw allow in on tailscale0 to any port %s proto tcp\n' "$port"
  done
}

ufw_rules() { ufw show added 2>/dev/null | grep '^ufw ' || true; }

firewall_ready() {
  command -v ufw >/dev/null 2>&1 || return 1
  local status
  status=$(ufw status verbose 2>/dev/null) || return 1
  grep -q '^Status: active' <<<"$status" &&
    grep -q 'deny (incoming)' <<<"$status" &&
    [[ "$(ufw_rules | sort)" == "$(ufw_wanted_rules | sort)" ]]
}

# The addresses SSH sessions to this NUC come from right now.
ssh_peers() {
  ss -Htn state established '( sport = :22 )' 2>/dev/null | awk '{print $4}' |
    sed -E 's/:[0-9]+$//; s/^\[//; s/\]$//; s/^::ffff://' | sort -u
}

setup_firewall() {
  if [[ -n "$LAN_SUBNET" ]] && firewall_ready; then already_done "Firewall"; return; fi

  say "Switching on the ufw firewall. Only SSH (22), HTTP (80) and HTTPS (443)"
  say "get in, and only from your home network and from Tailscale."
  printf '\n'
  choose_lan
  printf '\n'

  local peer outside=()
  while IFS= read -r peer; do
    [[ -n "$peer" ]] || continue
    ip_in_cidr "$peer" "$LAN_SUBNET" || ip_in_cidr "$peer" "$TAILSCALE_CGNAT" || outside+=("$peer")
  done < <(ssh_peers)
  if (( ${#outside[@]} )); then
    warn "SSH sessions from ${outside[*]} are outside $LAN_SUBNET and Tailscale:"
    warn "the firewall would block new logins from there. Log in from the Mac on"
    warn "your home network with the NUC's IPv4 address instead."
    if ! confirm "Switch the firewall on anyway?"; then
      skip_stage "Firewall: log in from the LAN, then re-run"
      return
    fi
  fi

  pkg_installed ufw || apt_install ufw
  local current
  current=$(ufw_rules)
  if [[ -n "$current" && "$(sort <<<"$current")" != "$(ufw_wanted_rules | sort)" ]]; then
    warn "The firewall has other rules, which this replaces:"
    note "$current"
    if ! confirm "Replace them?"; then
      skip_stage "Firewall: left as it was"
      return
    fi
  fi
  ufw --force reset >/dev/null
  ufw default deny incoming >/dev/null
  ufw default allow outgoing >/dev/null
  local rule
  while IFS= read -r rule; do
    # The rule's own words are ufw's arguments.
    # shellcheck disable=SC2086
    ufw ${rule#ufw } >/dev/null
  done < <(ufw_wanted_rules)
  ufw --force enable
  ufw status verbose
  did "Firewall: 22, 80 and 443 from $LAN_SUBNET and Tailscale only"
  pause
}

# ── Stage 6: Tailscale ────────────────────────────────────────────────────

FORWARDING_SETTINGS='# Written by setup-nuc.sh (ChargeOnSolar, #72): this NUC is a Tailscale subnet router.
net.ipv4.ip_forward = 1
net.ipv6.conf.all.forwarding = 1'

# forwarding_on: FORWARDING_SETTINGS are in place and in effect now.
forwarding_on() {
  file_is "$FORWARDING_CONF" "$FORWARDING_SETTINGS" || return 1
  local key value
  while IFS=' =' read -r key value; do
    [[ "$(sysctl -n "$key" 2>/dev/null)" == "$value" ]] || return 1
  done < <(grep -v '^#' <<<"$FORWARDING_SETTINGS")
}

tailscale_state() { tailscale status --json 2>/dev/null | jq -r '.BackendState // empty' 2>/dev/null; }

lan_advertised() {
  tailscale debug prefs 2>/dev/null | jq -e --arg lan "$LAN_SUBNET" '(.AdvertiseRoutes // []) | index($lan)' >/dev/null 2>&1
}

tailscale_ready() {
  pkg_installed tailscale && forwarding_on && [[ "$(tailscale_state)" == Running ]] &&
    [[ -n "$LAN_SUBNET" ]] && lan_advertised
}

setup_tailscale() {
  if tailscale_ready; then already_done "Tailscale, advertising $LAN_SUBNET"; return; fi

  say "Installing Tailscale, so you (and later the deploy from GitHub) can reach"
  say "the NUC from away. The NUC also passes Tailscale traffic on to your home"
  say "network (a 'subnet router'), so charge.<domain> works from away too."
  printf '\n'
  choose_lan
  printf '\n'

  if ! pkg_installed tailscale; then
    local codename
    codename=$(ubuntu_codename)
    if ! curl -fsSL "https://pkgs.tailscale.com/stable/ubuntu/$codename.noarmor.gpg" \
        -o /usr/share/keyrings/tailscale-archive-keyring.gpg ||
      ! curl -fsSL "https://pkgs.tailscale.com/stable/ubuntu/$codename.tailscale-keyring.list" \
        -o "$TAILSCALE_LIST" ||
      ! apt_update || ! apt_install tailscale; then
      skip_stage "Tailscale: couldn't install it (see above). Check the internet connection and re-run."
      return
    fi
  fi

  if ! forwarding_on; then
    write_file "$FORWARDING_CONF" 0644 "$FORWARDING_SETTINGS"
    sysctl -q -p "$FORWARDING_CONF"
  fi

  if [[ "$(tailscale_state)" == Running ]]; then
    tailscale set --advertise-routes="$LAN_SUBNET"
  else
    step "Tailscale now prints a link (https://login.tailscale.com/...)."
    step "Open it on your Mac and log in with your Tailscale account."
    note "  This waits until you have logged in."
    printf '\n'
    if ! tailscale up --advertise-routes="$LAN_SUBNET"; then
      skip_stage "Tailscale: login didn't finish. Re-run this wizard to try again."
      return
    fi
  fi
  printf '  %s✓%s on your tailnet as %s\n' "$GREEN" "$RESET" "$(tailscale ip -4 2>/dev/null | head -n1)"
  did "Tailscale, advertising $LAN_SUBNET"
  NEXT+=("Approve the route $LAN_SUBNET and turn off key expiry for this NUC in the Tailscale admin console: the Tailscale wizard (#74) walks you through it.")
  pause
}

# ── Stage 7: backup disk ──────────────────────────────────────────────────

FSTAB_OPTIONS="defaults,nofail,x-systemd.device-timeout=10s"

backup_mounted() {
  local source uuid
  source=$(findmnt -nvo SOURCE --mountpoint "$BACKUP_MOUNT" 2>/dev/null) || return 1
  uuid=$(fs_uuid "$source") || return 1
  [[ -n "$uuid" && "$(findmnt --fstab -nvo SOURCE --mountpoint "$BACKUP_MOUNT" 2>/dev/null)" == "UUID=$uuid" ]]
}

# The disks Ubuntu runs from: never a backup disk.
system_disks() {
  local mount source
  for mount in / /boot /boot/efi; do
    source=$(findmnt -nvo SOURCE --mountpoint "$mount" 2>/dev/null) || continue
    lsblk -nrspo NAME,TYPE "$source" | awk '$2 == "disk" { print $1 }'
  done | sort -u
}

# Disks that could be the 2.5" HDD: not the system disk, not a USB stick.
candidate_disks() {
  local system name type tran
  system=$(system_disks)
  while read -r name type tran; do
    [[ "$type" == disk && "$tran" != usb && "$name" != /dev/zram* ]] || continue
    grep -qxF "$name" <<<"$system" && continue
    printf '%s\n' "$name"
  done < <(lsblk -dnrpo NAME,TYPE,TRAN)
}

describe_disk() { lsblk -dno SIZE,MODEL "$1" | sed 's/  */ /g; s/^ //'; }

disk_is_blank() {
  [[ -z "$(wipefs -n --noheadings "$1" 2>/dev/null)" ]] &&
    (( $(lsblk -nrpo NAME "$1" | wc -l) == 1 ))
}

disk_in_use() { [[ -n "$(lsblk -nrpo MOUNTPOINTS "$1" | tr -d '[:space:]')" ]]; }

# fs_uuid / fs_type DEVICE: read from the disk itself (-p), not from udev's
# cache, which lags behind a disk that was just formatted.
fs_uuid() { blkid -p -s UUID -o value "$1" 2>/dev/null; }
fs_type() { blkid -p -s TYPE -o value "$1" 2>/dev/null; }

# The disk and partitions that hold a filesystem, with its type.
filesystems() {
  local device type
  while read -r device; do
    type=$(fs_type "$device") || continue
    [[ -n "$type" ]] && printf '%s %s\n' "$device" "$type"
  done < <(lsblk -nrpo NAME "$1")
  return 0
}

ext4_partitions() { filesystems "$1" | awk '$2 == "ext4" { print $1 }'; }

# show_files PARTITION: what is on it, mounted read-only for a look.
show_files() {
  local dir
  dir=$(mktemp -d)
  if mount -o ro "$1" "$dir" 2>/dev/null; then
    note "On $1 ($(df -h --output=used "$dir" | tail -n1 | tr -d ' ') used):"
    find "$dir" -mindepth 1 -maxdepth 1 -printf '      %f\n' | sort | head -n 20
    umount "$dir"
  fi
  rmdir "$dir"
}

# mount_by_uuid PARTITION: /backup, from /etc/fstab by UUID, from now on.
mount_by_uuid() {
  local uuid type tmp
  uuid=$(fs_uuid "$1")
  type=$(fs_type "$1")
  [[ -n "$uuid" && -n "$type" ]] || { warn "$1 has no filesystem UUID"; return 1; }
  install -d -m 0755 "$BACKUP_MOUNT"
  # While the HDD isn't mounted, nothing may write into the bare folder on the SSD.
  mountpoint -q "$BACKUP_MOUNT" || chattr +i "$BACKUP_MOUNT" || warn "couldn't lock the bare $BACKUP_MOUNT folder"
  [[ -f /etc/fstab.before-setup-nuc ]] || cp -p /etc/fstab /etc/fstab.before-setup-nuc
  tmp=$(mktemp)
  awk -v mount="$BACKUP_MOUNT" '$2 != mount' /etc/fstab > "$tmp"
  # nofail: a dead HDD must not stop the NUC from booting.
  printf 'UUID=%s %s %s %s 0 2\n' "$uuid" "$BACKUP_MOUNT" "$type" "$FSTAB_OPTIONS" >> "$tmp"
  cat "$tmp" > /etc/fstab
  rm -f "$tmp"
  printf '  %s✓ wrote%s %s → /etc/fstab (UUID=%s)\n' "$GREEN" "$RESET" "$BACKUP_MOUNT" "$uuid"
  systemctl daemon-reload
  mountpoint -q "$BACKUP_MOUNT" && umount "$BACKUP_MOUNT"
  mount "$BACKUP_MOUNT"
}

# format_disk DISK: one GPT partition with ext4 labelled "backup". Prints the partition.
format_disk() {
  local disk="$1" part="" tries
  # Called as part=$(format_disk ...) || ..., where set -e is off: check each step.
  wipefs -a -q "$disk" || return 1
  parted -s "$disk" mklabel gpt mkpart backup ext4 1MiB 100% >&2 || return 1
  udevadm settle
  for (( tries = 0; tries < 10; tries++ )); do
    part=$(lsblk -nrpo NAME,TYPE "$disk" | awk '$2 == "part" { print $1; exit }')
    [[ -n "$part" ]] && break
    sleep 1
  done
  [[ -n "$part" ]] || return 1
  mkfs.ext4 -q -F -L backup -m 0 "$part" >&2 || return 1
  udevadm settle
  printf '%s' "$part"
}

setup_backup_disk() {
  if backup_mounted; then already_done "Backup disk at $BACKUP_MOUNT"; return; fi

  say "Backups go to the 2.5\" HDD, mounted at $BACKUP_MOUNT, so they survive a dead SSD."
  printf '\n'

  # Mounted, but not by UUID: only /etc/fstab needs fixing.
  local mounted_source
  if mounted_source=$(findmnt -nvo SOURCE --mountpoint "$BACKUP_MOUNT" 2>/dev/null); then
    say "$mounted_source is already mounted at $BACKUP_MOUNT, but not by UUID."
    if ! mount_by_uuid "$mounted_source"; then
      skip_stage "Backup disk: couldn't mount $mounted_source by UUID (see above)"
      return
    fi
    did "Backup disk: $BACKUP_MOUNT now mounted by UUID"
    pause
    return
  fi

  local disks=() disk
  mapfile -t disks < <(candidate_disks)
  if (( ${#disks[@]} == 0 )); then
    warn "No second disk found. Is the HDD in the 2.5\" bay, and does the BIOS list it?"
    note "USB disks don't count, so an unplugged install stick is fine."
    skip_stage "Backup disk: none found. Fit the HDD and re-run."
    return
  fi
  if (( ${#disks[@]} == 1 )); then
    disk=${disks[0]}
  else
    say "More than one disk could be the HDD:"
    local i
    for i in "${!disks[@]}"; do say "  $((i + 1))) ${disks[$i]}  $(describe_disk "${disks[$i]}")"; done
    local CHOICE=""
    ask CHOICE "Number of the HDD:" || true
    if ! [[ "$CHOICE" =~ ^[0-9]+$ ]] || (( CHOICE < 1 || CHOICE > ${#disks[@]} )); then
      skip_stage "Backup disk: no disk chosen"
      return
    fi
    disk=${disks[$((CHOICE - 1))]}
  fi
  local name=${disk#/dev/}
  say "Found: ${BOLD}$disk${RESET}  $(describe_disk "$disk")"
  printf '\n'

  if disk_in_use "$disk"; then
    skip_stage "Backup disk: $disk is in use (mounted). Unmount it, then re-run."
    return
  fi

  local part="" ext4=()
  mapfile -t ext4 < <(ext4_partitions "$disk")
  if disk_is_blank "$disk"; then
    say "$disk is empty: no partitions, no filesystem."
    say "Formatting gives it one ext4 partition, labelled 'backup'."
    local TYPED=""
    ask TYPED "Type $name to format it (anything else stops):" || true
    if [[ "$TYPED" != "$name" ]]; then
      skip_stage "Backup disk: not formatted"
      return
    fi
    part=$(format_disk "$disk") || { skip_stage "Backup disk: formatting failed (see above)"; return; }
  elif (( ${#ext4[@]} == 1 )); then
    say "$disk already has an ext4 filesystem, maybe from an earlier install:"
    lsblk -o NAME,SIZE,FSTYPE,LABEL "$disk" | sed 's/^/    /'
    show_files "${ext4[0]}"
    if confirm "Use it as $BACKUP_MOUNT as it is, keeping its files?"; then
      part=${ext4[0]}
    fi
  fi

  if [[ -z "$part" ]]; then
    warn "$disk is NOT empty. Formatting it ERASES EVERYTHING on it:"
    lsblk -o NAME,SIZE,FSTYPE,LABEL "$disk" | sed 's/^/    /'
    local p
    while read -r p _; do show_files "$p"; done < <(filesystems "$disk")
    local TYPED=""
    ask TYPED "Type 'erase $name' to wipe and format it (anything else stops):" || true
    if [[ "$TYPED" != "erase $name" ]]; then
      skip_stage "Backup disk: $disk left untouched"
      return
    fi
    part=$(format_disk "$disk") || { skip_stage "Backup disk: formatting failed (see above)"; return; }
  fi

  if ! mount_by_uuid "$part"; then
    skip_stage "Backup disk: couldn't mount $part (see above)"
    return
  fi
  findmnt "$BACKUP_MOUNT"
  did "Backup disk: $part mounted at $BACKUP_MOUNT by UUID"
  pause
}

# ── Stage 8: /srv layout ──────────────────────────────────────────────────

setup_srv() {
  local dir missing=()
  for dir in "${SRV_DIRS[@]}"; do [[ -d "$dir" ]] || missing+=("$dir"); done
  if (( ${#missing[@]} == 0 )); then already_done "/srv layout"; return; fi

  say "Every stack on this home server gets a folder under /srv: the shared"
  say "proxy, and one per project. Owned by $USER_NAME, so you can edit them."
  printf '\n'
  for dir in "${missing[@]}"; do
    install -d -m 0755 -o "$USER_NAME" -g "$USER_NAME" "$dir"
    printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$dir"
  done
  did "/srv layout: ${missing[*]}"
  pause
}

# ── Before the stages ─────────────────────────────────────────────────────

preflight() {
  if (( EUID != 0 )); then
    echo "Run this wizard with sudo: sudo bash $0" >&2
    exit 1
  fi
  if [[ -z "$USER_NAME" || "$USER_NAME" == root ]]; then
    echo "Run it with sudo from your own account (not as root), so it knows who you are." >&2
    exit 1
  fi
  USER_HOME=$(getent passwd "$USER_NAME" | cut -d: -f6)
  # shellcheck source=/dev/null
  if [[ "$(. /etc/os-release && printf '%s' "$ID")" != ubuntu ]]; then
    echo "This wizard is for Ubuntu Server 26.04." >&2
    exit 1
  fi

  local tools=(jq curl ca-certificates parted) missing=() pkg
  for pkg in "${tools[@]}"; do pkg_installed "$pkg" || missing+=("$pkg"); done
  if (( ${#missing[@]} )); then
    echo "Installing what this wizard needs first: ${missing[*]}"
    if ! { apt_update && apt_install "${missing[@]}"; }; then
      echo "Couldn't install them. Check the internet connection and run again." >&2
      exit 1
    fi
  fi

  install -d -m 0700 /etc/chargeonsolar
  LAN_SUBNET=$(_existing LAN_SUBNET || detected_lan || true)
  [[ -n "$(_existing LAN_SUBNET || true)" ]] && LAN_CONFIRMED=1
  return 0
}

summary() {
  finish
  local line
  if (( ${#DONE[@]} )); then
    say "${BOLD}Done this run:${RESET}"
    for line in "${DONE[@]}"; do note "  - $line"; done
    printf '\n'
  fi
  if (( ${#ALREADY[@]} )); then
    say "${BOLD}Already done, skipped:${RESET}"
    for line in "${ALREADY[@]}"; do note "  - $line"; done
    printf '\n'
  fi
  NEXT+=("Part 2 of the NUC wizard (#73) puts ChargeOnSolar, the proxy, deploys and backups on top.")
  say "${BOLD}Next:${RESET}"
  for line in "${NEXT[@]}"; do note "  - $line"; done
  printf '\n'
}

run_wizard() {

TOTAL_STAGES=8

preflight

banner "NUC setup, part 1: the base system"

stage "SSH: key login only"
harden_ssh

stage "Docker Engine and Compose"
install_docker

stage "Docker without sudo"
add_docker_group

stage "Automatic security updates"
setup_upgrades

stage "Firewall"
setup_firewall

stage "Tailscale"
setup_tailscale

stage "Backup disk at $BACKUP_MOUNT"
setup_backup_disk

stage "Folders under /srv"
setup_srv

summary
}

run_wizard "$@"; exit
